package abstraction_interfaces.assigment_problems;

import java.util.*;public class ParcelShippingDesk {interface Insurable{double insurance(double value);}abstract static class Parcel{double w,v;Parcel(double w,double v){this.w=w;this.v=v;}abstract double charge();double insurance(){return this instanceof Insurable?((Insurable)this).insurance(v):0;}String type(){return getClass().getSimpleName().toUpperCase();}}static class Standard extends Parcel{Standard(double w,double v){super(w,v);}double charge(){return 40+10*w;}}static class Express extends Parcel implements Insurable{Express(double w,double v){super(w,v);}double charge(){return 80+15*w;}public double insurance(double v){return .02*v;}}static class Fragile extends Parcel implements Insurable{Fragile(double w,double v){super(w,v);}double charge(){return 40+10*w+50;}public double insurance(double v){return .02*v;}}public static void main(String[] z){Scanner s=new Scanner(System.in);int n=s.nextInt();double g=0;for(int i=0;i<n;i++){String t=s.next();double w=s.nextDouble(),v=s.nextDouble();Parcel p=t.equals("STANDARD")?new Standard(w,v):t.equals("EXPRESS")?new Express(w,v):new Fragile(w,v);double c=p.charge(),ins=p.insurance(),tot=c+ins;System.out.printf(Locale.US,"%s: Charge=%.2f Insurance=%.2f Total=%.2f%n",t,c,ins,tot);g+=tot;}System.out.printf(Locale.US,"Grand Total: %.2f%n",g);}}
